tenant_id = #{tenantId}
AND knowledge_base_id = #{knowledgeBaseId}

    AND status = #{status}


    AND (
        question LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(reason, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(comment, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(business_module, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(business_entity_id, '') LIKE CONCAT('%', #{keyword}, '%')
    )

mapper.select:
SELECT *
FROM knowledge_issues
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND business_module = #{businessModule}
  AND business_entity_id = #{businessEntityId}
ORDER BY
    CASE WHEN status = 'OPEN' THEN 0 ELSE 1 END,
    updated_at DESC
LIMIT #{limit}

SELECT
    COALESCE(SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END), 0) AS open_knowledge_issues,
    COALESCE(SUM(CASE WHEN source = 'NO_CONTEXT' THEN 1 ELSE 0 END), 0) AS no_context_issues
FROM knowledge_issues
WHERE tenant_id = #{tenantId}
  AND business_module = 'SUPPORT_TICKET'



  AND created_at >= #{startAt}
  AND created_at < #{endAt}

SELECT
    question,
    COUNT(*) AS total,
    MAX(created_at) AS latest_at
FROM knowledge_issues
WHERE tenant_id = #{tenantId}
  AND business_module = 'SUPPORT_TICKET'



  AND source = 'NO_CONTEXT'
  AND created_at >= #{startAt}
  AND created_at < #{endAt}
GROUP BY question
ORDER BY total DESC, latest_at DESC
LIMIT #{limit}
